H.background();
const w = H.W, h = H.H;
const n1 = Math.max(1.0, P.n1);               // dense medium (incident side), e.g. glass/water
const n2 = Math.min(n1-0.001 > 1 ? n1-0.001 : 1.0, Math.max(1.0, P.n2)); // less-dense medium
const inc = H.clamp(P.angle, 0, 89);          // angle of incidence from normal
const t1 = inc*Math.PI/180;
// Critical angle: sin(theta_c) = n2/n1 (only real when n1 > n2).
const ratio = H.clamp(n2/n1, 0, 1);
const tc = Math.asin(ratio);
const tcDeg = tc*180/Math.PI;
const s2 = (n1/n2)*Math.sin(t1);
const tir = s2 >= 1;                            // beyond critical angle -> all reflected
H.text("Total internal reflection:  sin(theta_c) = n2 / n1", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("n1 = " + n1.toFixed(2) + " (dense)   n2 = " + n2.toFixed(2) + "   theta_c = " + tcDeg.toFixed(1) + " deg   theta1 = " + inc.toFixed(0) + " deg", 24, 52, { color: H.colors.sub, size: 13 });
// Dense medium BELOW the interface (light travels up toward it).
const iy = h*0.46, px = w*0.5;
H.rect(50, iy, w-100, (h-30)-iy, { fill: "rgba(124,196,255,0.10)" });   // dense (n1) below
H.rect(50, 60, w-100, iy-60, { fill: "rgba(244,162,89,0.05)" });        // less dense (n2) above
H.line(50, iy, w-50, iy, { color: H.colors.accent, width: 2 });
H.line(px, 70, px, h-30, { color: H.colors.violet, width: 1.5, dash: [6,6] });
const Lin = Math.min((h-30)-iy, 210), Lout = Math.min(iy-70, 200);
// Incident ray travels UP from lower-left to the interface point.
const ix = px - Lin*Math.sin(t1), iyy = iy + Lin*Math.cos(t1);
H.arrow(ix, iyy, px, iy, { color: H.colors.warn, width: 3 });
let rx, ry, rcol, rlabel;
if (tir){
  // Total internal reflection: ray reflects back DOWN, same angle.
  rx = px + Lin*Math.sin(t1); ry = iy + Lin*Math.cos(t1); rcol = H.colors.warn; rlabel = "100% reflected";
} else {
  // Partially refracted into the upper medium, bending AWAY from normal.
  const t2 = Math.asin(H.clamp(s2,-1,1));
  rx = px + Lout*Math.sin(t2); ry = iy - Lout*Math.cos(t2); rcol = H.colors.good; rlabel = "refracted (escapes)";
}
H.arrow(px, iy, rx, ry, { color: rcol, width: 3 });
