let dx, dy;
if (ph<0.5){ const u=ph/0.5; dx=H.lerp(ix,px,u); dy=H.lerp(iyy,iy,u);} 
else { const u=(ph-0.5)/0.5; dx=H.lerp(px,rx,u); dy=H.lerp(iy,ry,u);} 
H.circle(dx, dy, 6, { fill: H.colors.yellow });
// Verdict caption.
H.text(tir ? "theta1 >= theta_c  ->  beam trapped (total internal reflection)" : "theta1 < theta_c  ->  beam refracts out into medium n2", 24, h-18, { color: tir?H.colors.warn:H.colors.good, size: 12 });
H.legend([{label:"incident", color:H.colors.warn},{label:rlabel, color:rcol}], w-190, 28);
